export function translate(message) {
  if (typeof message !== 'string') return message;
  if (Object.hasOwn(labels, message)) return labels[message];
  return message
    .replace(/^(.*?) must be a whole number from (.*?) to (.*?)\.$/, '$1 必须是 $2 至 $3 的整数。')
    .replace(/^Use at most (.*?) initial edges\.$/, '最多允许 $1 条初始边。')
    .replace(/^This radius contains only (.*?) edges\. Increase the radius or reduce the count\.$/, '该半径内只有 $1 条边，请增大半径或减小数量。')
    .replace(/^(Starting direction|Step length) must be from (.*?) to (.*?)\.$/, (_, key, min, max) => `${key === 'Starting direction' ? '初始方向' : '步长'}须在 ${min} 至 ${max} 之间。`)
    .replace(/^(Rule angles|Rule distances) must match the remainders and be from 0 to (.*?), or blank for the default\.$/, (_, key, max) => `${key === 'Rule angles' ? '规则转角' : '规则距离'}须与余数一一对应，取 0 至 ${max} 的值，留空使用默认值。`)
    .replace(/ must be a whole number between (.*?) and (.*?)\./g, '必须为 $1 到 $2 之间的整数。')
    .replace(/ must be between (.*?) and (.*?)\./g, '必须在 $1 到 $2 之间。')
    .replace(/ must be a finite number/g, '必须为有限数值')
    .replace(/ must be a safe integer/g, '必须为安全范围内的整数')
    .replace(/Choose a valid /g, '请选择有效的')
    .replace(/Invalid /g, '无效的')
    .replace(/Unknown /g, '未知的')
    .replace(/Unsupported /g, '不支持的');
}
